            "pxt.json": "{\n    \"name\": \"hw---rp2040\",\n    \"description\": \"RP2040 board\",\n    \"dependencies\": {\n        \"core---rp2040\": \"*\",\n        \"screen---st7735\": \"*\",\n        \"mixer---rp2040\": \"*\",\n        \"game\": \"*\"\n    },\n    \"files\": [\n        \"config.ts\",\n        \"basepins.d.ts\",\n        \"device.d.ts\"\n    ],\n    \"public\": true,\n    \"targetVersions\": {\n        \"target\": \"4.2.1\",\n        \"pxt\": \"13.2.1\"\n    },\n    \"card\": {\n        \"name\": \"R2\",\n        \"description\": \"Board based on Raspberry Pi RP2040\",\n        \"learnMoreUrl\": \"https://arcade.makecode.com/hardware#r2\",\n        \"cardType\": \"hw\",\n        \"imageUrl\": \"/static/hardware/rpi-pico.jpg\"\n    },\n    \"compileServiceVariant\": \"rp2040\",\n    \"cppDependencies\": {\n        \"accelerometer\": \"file:../accelerometer\"\n    },\n    \"skipLocalization\": true,\n    \"yotta\": {\n        \"optionalConfig\": {\n            \"DEVICE_JACDAC_DEBUG\": 1\n        },\n        \"config\": {\n            \"DEVICE_USB\": 1,\n            \"DEVICE_WEBUSB\": 1\n        }\n    },\n    \"hidden\": true,\n    \"dalDTS\": {\n        \"corePackage\": \"../core---rp2040\"\n    }\n}\n"
