            "_locales/fr/calliope-mini-strings.json": "{\n  \"pins.C10\": \"Broche C10 du connecteur du Calliope mini (analogique, PWM, colonne 5 de la matrice LED)\",\n  \"pins.C11\": \"Broche C11 du connecteur du Calliope mini (bouton B)\",\n  \"pins.C16\": \"Broche C16 du connecteur du Calliope mini (analogique, PWM, Grove A1 RX)\",\n  \"pins.C18\": \"Broche C18 du connecteur du Calliope mini (analogique, PWM, colonne 3 de la matrice LED)\",\n  \"pins.C4\": \"Broche C4 du connecteur du Calliope mini (analogique, PWM, colonne 1 de la matrice LED)\",\n  \"pins.C5\": \"Broche C5 du connecteur du Calliope mini (bouton A)\",\n  \"pins.C6\": \"Broche C6 du connecteur du Calliope mini (numérique, PWM, colonne 4 de la matrice LED)\",\n  \"pins.C7\": \"Broche C7 du connecteur du Calliope mini (numérique, PWM, colonne 2 de la matrice LED)\",\n  \"pins.PAD0\": \"Broche P0 du Calliope mini (analogique, PWM, tactile)\",\n  \"pins.PAD0|block\": \"P0\",\n  \"pins.PAD1\": \"Broche P1 du Calliope mini (analogique, PWM, tactile)\",\n  \"pins.PAD1|block\": \"P1\",\n  \"pins.PAD2\": \"Broche P2 du Calliope mini (analogique, PWM, tactile)\",\n  \"pins.PAD2|block\": \"P2\",\n  \"pins.PAD3\": \"Broche P3 du Calliope mini (numérique, PWM, tactile)\",\n  \"pins.PAD3|block\": \"P3\"\n}",
